-- PT117-S4-Q4. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT117-S4-Q4$batch09$ AND q.stimulus=$batch09$Statistics indicating a sudden increase in the incidence of a problem often merely reflect a heightened awareness of the problem or a greater ability to record its occurrence. Hence we should be wary of proposals for radical solutions to problems when those proposals are a reaction to new statistical data.$batch09$ AND q.prompt=$batch09$The argumentation conforms most closely to which one of the following principles?$batch09$ AND q.correct_choice=$batch09$A$batch09$) THEN RAISE EXCEPTION 'Question changed: PT117-S4-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT117-S4-Q4$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S4-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT117-S4-Q4$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Be wary of proposals for radical solutions that are reactions to new statistics.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$A sudden statistical jump in a problem often just reflects greater awareness of the problem or better recording of it.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The argument doesn't deny the problem exists. It says the jump in the numbers may come from us noticing more, not from the problem getting worse. If only our awareness has changed, that's no reason for a radical response. The principle connects those ideas.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Greater awareness of a problem doesn't by itself justify a radical solution.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT117-S4-Q4$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$"Better cognizance" is the heightened awareness from the evidence. "Does not warrant a radical solution" is the wariness in the conclusion. If the statistics only show better cognizance, A tells us not to go radical.$batch09$), ($batch09$B$batch09$, $batch09$This is the trap, picked by 10%. It sounds cautious in the same way. But the argument never doubts that the problem exists. It doubts that the problem has suddenly grown. B also covers any attempt to stop a problem, not radical ones.$batch09$), ($batch09$C$batch09$, $batch09$The argument is wary of solutions driven by new statistics. Basing them on statistics alone is the reverse.$batch09$), ($batch09$D$batch09$, $batch09$Nobody is manipulating the data. The numbers can be completely accurate and still reflect awareness more than a real increase.$batch09$), ($batch09$E$batch09$, $batch09$Radical solutions might backfire, but that isn't the argument's reason for caution. Its reason is that the statistics may not mean what they seem to.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT117-S4-Q4$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
